public class InvertirArray {
    public static void main(String[] args) {
        int[] numeros = {1, 2, 3, 4, 5};
        for (int i = 0, j = numeros.length - 1; i < j; i++, j--) {
            int temp = numeros[i];
            numeros[i] = numeros[j];
            numeros[j] = temp;
        }
        for (int n : numeros) System.out.print(n + " ");
        System.out.println();
    }
}

