public class ContarUnicos {
    public static void main(String[] args) {
        int[] datos = {1, 1, 2, 3, 3, 3, 4, 5, 5};
        int unicos = 1;
        for (int i = 1; i < datos.length; i++) {
            if (datos[i] != datos[i - 1]) unicos++;
        }
        System.out.println("Únicos: " + unicos);
    }
}

